  it('passes schema-valid input, including extra properties, through unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {query: 'weather', extra: 42};
    const execute = jest.fn(async () => 'ok');
    registry.register(
      {
        name: 'lookup',
        description: 'Lookup',
        inputSchema: {type: 'object', properties: {query: {type: 'string'}}, required: ['query']},
      },
      execute
    );

    await registry.execute('lookup', input);

    expect(execute).toHaveBeenCalledTimes(1);
    expect(execute).toHaveBeenCalledWith(input, undefined);
  });

  it('throws for an unknown tool name', async () => {
    await expect(new ToolRegistry().execute('missing', {})).rejects.toThrow('Unknown tool: missing');
  });

  it('uses the schema resolved for each function-valued definition call', async () => {
    const registry = new ToolRegistry();
    let call = 0;
    registry.register(
      () => ({
        name: 'dynamic',
        description: 'Dynamic schema',
        inputSchema: call++ === 0
          ? {type: 'object', properties: {first: {type: 'string'}}, required: ['first']}
          : {type: 'object', properties: {second: {type: 'string'}}, required: ['second']},
      }),
      async () => 'ok'
    );

    const result = await registry.execute('dynamic', {second: 'valid'});

    expect(result.result).toBe('ok');
  });

  it('reuses a static schema validator across executions', async () => {
    const registry = new ToolRegistry();
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    registry.register(
      {
        name: 'static',
        description: 'Static schema',
        inputSchema: {type: 'object', properties: {value: {type: 'string'}}},
      },
      async () => 'ok'
    );
    const compileCallsAfterRegister = compile.mock.calls.length;

    for (let index = 0; index < 10; index += 1) await registry.execute('static', {value: 'valid'});

    expect(compile.mock.calls).toHaveLength(compileCallsAfterRegister);
    compile.mockRestore();
  });
});
EOF
